```yaml
name: CLA Check

on:
  pull_request:
    types: [opened, synchronize, reopened]

jobs:
  check-clause:
    runs-on: ubuntu-latest
    steps:
      - name: Verify CLA text in PR description
        uses: actions/github-script@v6
        with:
          script: |
            const requiredText = "By submitting this pull request, I confirm that you can use, modify, copy, and redistribute this contribution, under the terms of your choice.";
            const pr = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: context.issue.number
            });
            const body = pr.data.body || "";
            if (!body.includes(requiredText)) {
              core.setFailed("CLA text not found in PR description.");
            }

      - name: Comment on missing CLA
        if: failure()
        uses: thollander/actions-comment-pull-request@e4a76dd2b0a3c2027c3fd84147a67c22ee4c90fa
        with:
          message: |
            ❌ **CLA missing**  
            Please add the required CLA text to your PR description:  
            > By submitting this pull request, I confirm that you can use, modify, copy, and redistribute this contribution, under the terms of your choice.
          github-token: ${{ secrets.GITHUB_TOKEN }}
          pr-number: ${{ github.event.pull_request.number }}
          comment-tag: cla-check
          mode: replace
```

